<?php namespace App\Features\Stock\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Relations\BelongsTo;use App\Features\Stock\Enums\StockStatus;
class Stock extends Model {use HasFactory;protected $fillable=['user_id','name','sku','description','quantity','unit','price','min_stock','status','cover_image_path'];protected function casts():array{return ['quantity'=>'integer','min_stock'=>'integer','price'=>'decimal:2'];}public function user():BelongsTo{return $this->belongsTo(\App\Models\User::class);}public function syncStatus():void{$this->status=StockStatus::fromQuantity((int)$this->quantity,(int)$this->min_stock)->value;}public function adjust(int $amount):void{$this->quantity=max(0,(int)$this->quantity+$amount);$this->syncStatus();$this->save();}}
